#!/usr/bin/env node
// GENERATED by scripts/gen/build.mjs from gen/tools/slice-inventory.mjs - edit the sources, not this file.
// Inventory of the vertical slices in a repository: for every slice (a feature folder, or a single feature file) it shows which
// parts exist - endpoint, handler, validation, an authorization hint, a cancellation token - and whether any test mentions the slice.
// Heuristic (text based): it points at slices that look incomplete; confirm each in context.
// Usage: node slice-inventory.mjs [path] [--module <Name>] [--json] [--strict]
//   --strict: exit 1 when any slice has no endpoint-or-handler, no authorization hint or no test
import { readdirSync, readFileSync } from "node:fs";
import { basename, dirname, join, relative, resolve } from "node:path";
const SKIP_DIRS = new Set([
  "bin",
  "obj",
  "node_modules",
  ".git",
  ".vs",
  "TestResults",
  "artifacts",
]);
const ROLE_SUFFIX =
  /\.(Contracts|Tests|UnitTests|IntegrationTests|Infrastructure|Domain|Application|Api|Endpoints|Migrations)$/i;
const SHARED_NAME = /(^|\.)(Shared|SharedKernel|BuildingBlocks|Common|Kernel)(\.|$)/i;
// Composition roots reference every module's implementation by design, so they belong to no module.
const HOST_NAME = /(^|\.)(Host|WebHost|AppHost|Bootstrapper)(\.|$)/i;
// Vendor/framework namespace roots: never a module, even when a module shares a segment name (Microsoft.AspNetCore.Identity vs module Identity).
const posix = (p) => p.split("\\").join("/");

function* walkFiles(dir, depth = 0) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    if (e.isDirectory()) {
      if (!SKIP_DIRS.has(e.name) && depth < 24) yield* walkFiles(join(dir, e.name), depth + 1);
    } else yield join(dir, e.name);
  }
}

// Target framework set in the nearest Directory.Build.props above the project (stops at the repo root).
function inheritedTfm(file, root) {
  for (let d = dirname(file); ; d = dirname(d)) {
    const t = tryRead(join(d, "Directory.Build.props"));
    const m = t && /<TargetFrameworks?>([^<$]+)</i.exec(t);
    if (m) return m[1];
    if (d === root || d === dirname(d)) return undefined;
  }
}

function readProjects(root) {
  const projects = [];
  for (const file of walkFiles(root)) {
    if (!file.endsWith(".csproj")) continue;
    // XML comments are ignored: a commented-out reference is not a reference.
    const text = readFileSync(file, "utf8").replace(/<!--[\s\S]*?-->/g, " ");
    const all = (re) => [...text.matchAll(re)].map((m) => m[1]);
    const name = basename(file, ".csproj");
    projects.push({
      name,
      file,
      dir: dirname(file),
      rel: posix(relative(root, file)),
      refs: all(/<ProjectReference\s[^>]*?Include\s*=\s*["']([^"']+)["']/gi)
        .map((r) =>
          r.replace(
            /\$\((MSBuildThisFileDirectory|MSBuildProjectDirectory)\)[\\/]?/i,
            `${dirname(file)}/`,
          ),
        )
        .filter((r) => !r.includes("$("))
        .map((r) => resolve(dirname(file), r.split("\\").join("/"))),
      packages: all(/<PackageReference\s[^>]*?Include\s*=\s*["']([^"']+)["']/gi),
      frameworks: all(/<FrameworkReference\s[^>]*?Include\s*=\s*"([^"]+)"/gi),
      ivt: all(/<InternalsVisibleTo\s[^>]*?Include\s*=\s*["']([^"']+)["']/gi).map((n) =>
        n.split(",")[0].trim(),
      ),
      tfms: (/<TargetFrameworks?>([^<]+)</i.exec(text)?.[1] ?? inheritedTfm(file, root) ?? "")
        .split(";")
        .map((t) => t.trim())
        .filter(Boolean),
      isTest:
        /<IsTestProject>\s*true/i.test(text) ||
        /Microsoft\.NET\.Test\.Sdk/.test(text) ||
        /\.(Unit|Integration)?Tests?$/i.test(name),
    });
  }
  return detectModules(projects, root);
}

function detectModules(projects, root) {
  let config = {};
  try {
    config = JSON.parse(readFileSync(join(root, "modules.json"), "utf8"));
  } catch {
    // no config: use conventions
  }
  const stripRoles = (name) => {
    let base = name;
    for (let m = ROLE_SUFFIX.exec(base); m; m = ROLE_SUFFIX.exec(base))
      base = base.slice(0, m.index);
    return base || name;
  };
  const bases = projects.map((p) => stripRoles(p.name));
  const multi = bases.filter((b) => b.includes("."));
  const first = multi.map((b) => b.split(".")[0]);
  const top = [...new Set(first)]
    .map((s) => [s, first.filter((x) => x === s).length])
    .sort((a, b) => b[1] - a[1])[0];
  const prefix = top && multi.length >= 3 && top[1] / bases.length >= 0.8 ? `${top[0]}.` : "";
  // Path-boundary prefix match; the longest matching prefix wins (so "src/Orders" does not swallow "src/Orders2").
  const under = (rel, x) => {
    const base = x.replace(/\/+$/, "");
    return rel === base || rel.startsWith(`${base}/`);
  };
  const configured = (rel) => {
    const hits = [
      ...Object.entries(config.modules ?? {}).flatMap(([module, paths]) =>
        paths.filter((x) => under(rel, x)).map((x) => ({ module, len: x.length })),
      ),
      ...(config.shared ?? [])
        .filter((x) => under(rel, x))
        .map((x) => ({ module: null, len: x.length })),
    ].sort((a, b) => b.len - a.len);
    return hits[0];
  };

  // When the repository clearly organises modules as Modules/<Name>/ (at least 4 projects), everything outside that folder
  // (hosts, building blocks, tools, cross-cutting tests) belongs to no module: a product or company name is not a module.
  const pathHit = (p) => /(?:^|\/)[Mm]odules\/([^/]+)\//.exec(`/${p.rel}`);
  const pathMode = !config.modules && projects.filter((p) => pathHit(p)).length >= 4;
  const fixed = new Set(); // projects whose module came from modules.json or the Modules/<Name> folder

  for (const [i, p] of projects.entries()) {
    let module;
    const hit = configured(p.rel);
    const m = pathHit(p);
    if (hit) module = hit.module;
    else if (m) module = m[1];
    else if (pathMode && !p.isTest) module = null; // tests fall through to their name, then to what they reference
    else if (SHARED_NAME.test(bases[i]) || HOST_NAME.test(bases[i])) module = null;
    // Acme.Api / Acme.Web: nothing left after the company prefix, so it is the host, not a module named "Acme".
    else if (prefix && bases[i] === prefix.slice(0, -1)) module = null;
    else module = prefix && bases[i].startsWith(prefix) ? bases[i].slice(prefix.length) : bases[i];
    if (hit || m) fixed.add(p);
    p.module = module;
    // "Zivex.Modules.Contracts" is the implementation of a module that is called Contracts; "Quotes.Contracts" is a contract project.
    const named =
      /\.Contracts$/i.test(p.name) &&
      !(module === "Contracts" && !/\.Contracts\.Contracts$/i.test(p.name));
    p.role = p.isTest ? "test" : named ? "contracts" : "impl";
    if (module === null && !p.isTest) p.role = "shared";
  }

  // A test project belongs to the module its name points at; otherwise to the one module it references. One that references
  // several modules (architecture, integration, security suites) is cross-cutting and belongs to none.
  const byPath = new Map(projects.map((p) => [resolve(p.file), p]));
  const known = new Set(projects.filter((x) => !x.isTest && x.module).map((x) => x.module));
  for (const p of projects.filter((x) => x.isTest && !fixed.has(x))) {
    if (p.module && known.has(p.module)) continue; // the name points at a real module (Orders.Tests -> Orders): keep it
    const mods = new Set(
      p.refs
        .map((r) => byPath.get(r))
        .filter((t) => t && !t.isTest && t.module)
        .map((t) => t.module),
    );
    if (mods.size === 1) p.module = [...mods][0];
    else if (mods.size > 1 || pathMode) p.module = null;
  }
  return projects;
}

const moduleNames = (projects) =>
  [...new Set(projects.map((p) => p.module).filter(Boolean))].sort();
function tryRead(path) {
  try {
    return readFileSync(path, "utf8");
  } catch {
    return undefined;
  }
}

// Blank out /* ... */ comments but keep the newlines, so line numbers stay right.

const args = process.argv.slice(2);
const flagValue = (n) => (args.includes(n) ? args[args.indexOf(n) + 1] : undefined);
const onlyModule = flagValue("--module");
const root = resolve(
  args.find((a, i) => !a.startsWith("--") && args[i - 1] !== "--module") ?? process.cwd(),
);
const projects = readProjects(root);
const modules = moduleNames(projects);
const ROOT_NAMES = /^(features|usecases|slices)$/i;
const MAPPING = /\.Map(Get|Post|Put|Delete|Patch)\s*\(|static\s+void\s+Map\s*\(|\bIFeature\b/;
const HANDLER = /HandleAsync\s*\(|class\s+\w*Handler\b/;
const csOf = (dir) => [...walkFiles(dir)].filter((f) => f.endsWith(".cs"));
const text = (f) => tryRead(f) ?? "";

const scope = projects.filter(
  (p) => p.role === "impl" && (!onlyModule || p.module?.toLowerCase() === onlyModule.toLowerCase()),
);
const testFiles = projects
  .filter((p) => p.role === "test")
  .map((p) => ({ module: p.module, files: csOf(p.dir).map((f) => ({ path: f, text: text(f) })) }));

function* dirsNamed(dir, depth = 0) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    if (!e.isDirectory() || SKIP_DIRS.has(e.name) || depth > 12) continue;
    if (ROOT_NAMES.test(e.name)) yield join(dir, e.name);
    else yield* dirsNamed(join(dir, e.name), depth + 1);
  }
}

const slices = [];
for (const project of scope) {
  for (const rootDir of dirsNamed(project.dir)) {
    const add = (name, group, files) =>
      slices.push({
        module: project.module ?? "(none)",
        project: project.name,
        slice: name,
        group,
        files,
      });
    for (const e of readdirSync(rootDir, { withFileTypes: true })) {
      const path = join(rootDir, e.name);
      if (e.isFile() && e.name.endsWith(".cs")) {
        if (MAPPING.test(text(path)) || HANDLER.test(text(path)))
          add(basename(e.name, ".cs"), "", [path]);
        continue;
      }
      if (!e.isDirectory() || SKIP_DIRS.has(e.name)) continue;
      const files = csOf(path);
      const mapped = files.filter((f) => MAPPING.test(text(f)));
      // Features/<Module>/<Action>.cs: several mapped files in one folder are separate slices; otherwise the folder is the slice.
      if (mapped.length >= 2) for (const f of mapped) add(basename(f, ".cs"), e.name, [f]);
      else if (files.length) add(e.name, "", files);
    }
  }
}

const mentions = (name, module) => {
  // The slice name may continue with an uppercase letter or a non-letter (CancelOrderTests, CancelOrderHandlerTests, CancelOrder_x) but not a lowercase one (CancelOrders).
  const re = new RegExp(`\\b${name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}(?![a-z])`);
  const pool = testFiles.filter(
    (t) => !module || t.module === module || t.module == null || !modules.length,
  );
  return pool.flatMap((t) => t.files).filter((f) => re.test(f.text) || re.test(basename(f.path)))
    .length;
};

const rows = slices.map((s) => {
  const body = s.files.map(text).join("\n");
  const row = {
    module: s.module,
    slice: s.slice,
    group: s.group || undefined,
    files: s.files.map((f) => posix(relative(root, f))),
    endpoint: MAPPING.test(body),
    handler: HANDLER.test(body),
    validation: /Validator|Validate\s*\(|ValidationProblem|DataAnnotations|\[Required/.test(body),
    authorization:
      /RequireAuthorization|RequireModule|\[Authorize|Capabilities|EnsureAsync|AuthorizeAsync|AllowAnonymous/.test(
        body,
      ),
    cancellation: /CancellationToken|\bct\b/.test(body),
    tests: mentions(s.slice, s.module === "(none)" ? undefined : s.module),
  };
  const hasInput = /record\s+\w*(Request|Command|Input)\b/.test(body);
  row.missing = [
    !row.endpoint && !row.handler && "endpoint or handler",
    !row.authorization && "authorization",
    hasInput && !row.validation && "validation",
    !row.cancellation && "cancellation token",
    row.tests === 0 && "tests",
  ].filter(Boolean);
  return row;
});

if (args.includes("--json")) console.log(JSON.stringify({ modules, slices: rows }, null, 2));
else if (!rows.length)
  console.log(
    `No Features, UseCases or Slices folder with slices found${onlyModule ? ` for module ${onlyModule}` : ""}: this code may not use vertical slices.`,
  );
else {
  const yes = (b) => (b ? "yes" : " - ");
  console.log(`${"module".padEnd(14)} ${"slice".padEnd(30)} endpt hndlr valid  auth cancel tests`);
  for (const r of rows) {
    console.log(
      `${r.module.padEnd(14)} ${(r.group ? `${r.group}/${r.slice}` : r.slice).padEnd(30)} ${yes(r.endpoint).padStart(5)} ${yes(r.handler).padStart(5)} ${yes(r.validation).padStart(5)} ${yes(r.authorization).padStart(5)} ${yes(r.cancellation).padStart(6)} ${String(r.tests).padStart(5)}`,
    );
  }
  const weak = rows.filter((r) => r.missing.length);
  console.log(
    `\n${rows.length} slice(s), ${weak.length} with gaps (heuristic: confirm in context):`,
  );
  for (const r of weak)
    console.log(
      `  ${r.group ? `${r.group}/` : ""}${r.slice} (${r.module}): missing ${r.missing.join(", ")}`,
    );
}
if (
  args.includes("--strict") &&
  rows.some((r) =>
    r.missing.some((m) => ["endpoint or handler", "authorization", "tests"].includes(m)),
  )
)
  process.exit(1);
